package provider
import("context";"encoding/json";"io";"net/http";"net/http/httptest";"strings";"testing")
func TestNotifyEvolutionUsesSharedProviderCredentialsWithoutLeakingKey(t *testing.T){const secret="fixture-only-secret-never-log-or-persist";called:=false;server:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){called=true;if r.URL.Path!="/v1/mind/provider/heartbeat"{t.Errorf("unexpected path: %s",r.URL.Path)};if got:=r.Header.Get("Authorization");got!="Bearer "+secret{t.Error("shared provider credential not used")};body,err:=io.ReadAll(r.Body);if err!=nil{t.Fatal(err)};if strings.Contains(string(body),secret){t.Error("provider key leaked into request body")};var obj map[string]any;if err:=json.Unmarshal(body,&obj);err!=nil{t.Fatal(err)};if obj["core"]!="USECT-TWO"{t.Errorf("unexpected event envelope: %+v",obj)};w.WriteHeader(http.StatusAccepted)}));defer server.Close();t.Setenv("REVELACODE_PROVIDER_URL",server.URL);t.Setenv("REVELACODE_PROVIDER_KEY",secret);mesh:=FromEnvironment();if !mesh.Configured(){t.Fatal("expected the existing Core-One provider env names to configure Mind")};if err:=mesh.NotifyEvolution(context.Background(),map[string]any{"status":"await_merge","version":"v0.1.0"});err!=nil{t.Fatal(err)};if !called{t.Fatal("provider notification was not sent")}}
